#!/usr/bin/env python3
import base64
import gzip
import hashlib
import pathlib
import subprocess
import sys
import tempfile

root = pathlib.Path(sys.argv[1]).resolve()
if not (root / "go.mod").is_file():
    raise SystemExit("target is not a HYZoraX source tree")

protocol = root / "internal/helper/protocol.go"
if "const ProtocolVersion = 21" not in protocol.read_text():
    raise SystemExit("Protocol V21 invariant failed")

expected_before = {
    "internal/web/static/index.html": "b70b0863ed1070cccfc918d5d918af3cdb25903f1c3d515271c3abfb9a7ce1ba",
    "internal/web/static/app.css": "b6d6e86e2cb372a676ce97cf98cbb6610ccb2fd0ae47a17d42cdd2c71d723e04",
    "internal/web/static/app.js": "dde412648367d8dae2808c2dac6540998eec67c884537ce0135f69ab08291f95",
    "internal/web/assets_test.go": "1ba7f51d47d25b419302df0779f843863c9c66019c91f91427611abd67846f6e",
    "internal/httpapi/app_test.go": "0afe56f5fd4f337bfe9d7e035a0b057c0da5ca1cb4e460f9d7a9e277414725d4",
}
for rel, expected in expected_before.items():
    actual = hashlib.sha256((root / rel).read_bytes()).hexdigest()
    if actual != expected:
        raise SystemExit(f"V1.8.0 baseline mismatch: {rel}: {actual}")

payload = ""
patch_data = gzip.decompress(base64.b64decode(payload))
with tempfile.NamedTemporaryFile() as handle:
    handle.write(patch_data)
    handle.flush()
    subprocess.run(
        ["patch", "--batch", "--forward", "--strip=0", "--input", handle.name],
        cwd=root,
        check=True,
    )

expected_after = {
    "internal/web/static/index.html": "8c78fed6b8c7e210b2d814d514652fdb215507cf30e7d54a317702ac16e57522",
    "internal/web/static/app.css": "0e6cbf2195aef540688fe5416359863960bf730c32ec2c566d04d3be7677c23b",
    "internal/web/static/app.js": "4796f8adbc27e2ae8066861f7f84af5889d2c6a3d4e9ef2e4ebd9dd015969dee",
    "internal/web/assets_test.go": "6a2d8a465e6d484cb20d1091eca3e24ddfb3f2c0916620c8ce6c3f2d8719158b",
    "internal/httpapi/app_test.go": "2adf050923ba4feee2d9cf9927b3aa28e60fa27f70629942cc7619cd5fea0e05",
}
for rel, expected in expected_after.items():
    actual = hashlib.sha256((root / rel).read_bytes()).hexdigest()
    if actual != expected:
        raise SystemExit(f"V1.8.1 result mismatch: {rel}: {actual}")

print("V1.8.1 branded workspace and File Manager patch applied")
